import {assertAttributes,assertEmptyElement,canonicalize,createMarkupSurfaceHostFacet,sameType,sealGraphFragment,textAttribute} from '@hypit/hypit/author-kit';
import {compositionTypes} from '@hypit/hypit/composition';
import {mediaTypes} from '@hypit/hypit/media';
import {timelineTypes} from '@hypit/hypit/timeline';
import {spatialTypes} from '@hypit/hypit/spatial';
import {temporalTypes} from '@hypit/hypit/temporal';
import {createTemporalWindowProjection,temporalWindowAttributeNames,temporalWindowAttributeVocabulary} from '@hypit/hypit/temporal-markup';
import {createStudioTrackCompanionHostFacet,temporalLineageFor,textLayer} from '@hypit/hypit/studio-adapter';

// This helper is shipped inside each package: a consumer never needs a sibling package.
export function motionPackage(definition,render){
 const module={name:definition.packageName,version:'1'},options={module,name:'Options'},port=(name,type)=>({name,type});
 const value=v=>({kind:'inline',value:canonicalize(v)}),unwrap=r=>r.value.value;
 const variants=[{name:'motion',tag:'Motion',image:false},...(definition.image?[{name:'image-motion',tag:'ImageMotion',image:true}]:[])];
 const nativeFonts=definition.nativeFonts||[],nativeIds=nativeFonts.map(f=>f.id);
 const inputsFor=v=>[port('timeline',timelineTypes.track),port('canvas',spatialTypes.canvas),port('window',temporalTypes.window),port('font',mediaTypes.fontArtifact),...nativeIds.map(id=>port(id,mediaTypes.fontArtifact)),port('options',options),...(v.image?[port('image',mediaTypes.blobArtifact)]:[])];
 const manifest={format:'hypit.module@1',...module,dependencies:[...new Map([compositionTypes.visualTrack,mediaTypes.fontArtifact,mediaTypes.blobArtifact,timelineTypes.track,spatialTypes.canvas,temporalTypes.window].map(type=>[type.module.name,{module:type.module}])).values()],types:[{name:'Options'}],capabilities:[],producers:variants.map(v=>({name:v.name,inputs:inputsFor(v),outputs:[port('track',compositionTypes.visualTrack)],needs:[]}))};
 const surfaces=variants.map(v=>{
  const inputs=inputsFor(v),fragment=sealGraphFragment({inputs,operations:[{id:'draw',producer:{module,name:v.name},inputs:Object.fromEntries(inputs.map(p=>[p.name,{kind:'fragment-input',name:p.name}])),result:{kind:'output',name:'track'}}],exports:[{name:'track',type:compositionTypes.visualTrack,root:{kind:'fragment-operation',operation:'draw'}}]});
  return createMarkupSurfaceHostFacet({module,declaration:{name:v.name,tag:v.tag,mode:'structured',outputs:[compositionTypes.visualTrack,temporalTypes.window,temporalTypes.instant,temporalTypes.windowSpec,temporalTypes.instantSpec,options],vocabulary:{summary:definition.description,attributes:[...['id','timeline','canvas','font',...nativeIds,...(v.image?['image']:[])].map(name=>({name,kind:name==='id'?'text':'expression',required:true,summary:name})),...definition.parameters.map(p=>({name:p.key,kind:'text',required:false,summary:p.label})),...temporalWindowAttributeVocabulary],ports:[{name:'track',type:compositionTypes.visualTrack,summary:definition.name+' · 可编辑画面'}]}},handler:({element,resolveReference})=>{
   assertAttributes(element,['id','timeline','canvas','font',...nativeIds,...(v.image?['image']:[]),...definition.parameters.map(p=>p.key),...temporalWindowAttributeNames]);assertEmptyElement(element);
   const id=textAttribute(element,'id'),ref=(name,type)=>{const raw=element.attributes[name];if(raw?.kind!=='reference')throw Error(name+' 需要引用');const r=resolveReference(raw.path);if(!r||!sameType(type,r.type))throw Error(name+' 类型不匹配');return r;};
   const timeline=ref('timeline',timelineTypes.track),window=createTemporalWindowProjection({id:id+'.window',element,timeline,resolveReference}),config={id};
   for(const p of definition.parameters){const raw=element.attributes[p.key]??p.default;let parsed=p.type==='number'?Number(raw):String(raw);if(p.type==='number'&&(!Number.isFinite(parsed)||(p.min!==undefined&&parsed<p.min)||(p.max!==undefined&&parsed>p.max)))throw Error(p.label+' 超出范围');if(p.type==='text'){if(p.maxLength!==undefined&&[...parsed].length>p.maxLength)throw Error(p.label+' 最多 '+p.maxLength+' 个字符');if(p.key==='brand'&&!parsed.trim())throw Error('品牌名不能为空');parsed=parsed.slice(0,240);if(['background','color','accent','secondary'].includes(p.key)&&!/^#[0-9a-f]{3}(?:[0-9a-f]{3})?$/i.test(parsed))throw Error(p.label+' 请使用十六进制颜色');if(['transparent','captions'].includes(p.key)&&!['true','false'].includes(parsed))throw Error(p.label+' 只能为 true 或 false');}if(['background','color','accent','secondary'].includes(p.key)&&parsed.length===4)parsed='#'+parsed.slice(1).split('').map(v=>v+v).join('');if(p.key==='values'){const list=parsed.split(/[,，]/);if(list.length<2||list.length>12||list.some(v=>!v.trim()||!Number.isFinite(Number(v))||Number(v)<0))throw Error('数据需要 2–12 个非负数，以逗号分隔');}config[p.key]=parsed;}
   return {records:[...window.records,{id:id+'.options',type:options,value:value(config),range:element.range}],fragments:[...window.fragments,fragment],components:[...window.components,{id,fragment:fragment.id,inputs:{timeline:timeline.ref,canvas:ref('canvas',spatialTypes.canvas).ref,font:ref('font',mediaTypes.fontArtifact).ref,...Object.fromEntries(nativeIds.map(id=>[id,ref(id,mediaTypes.fontArtifact).ref])),window:window.ref,options:{kind:'record',id:id+'.options'},...(v.image?{image:ref('image',mediaTypes.blobArtifact).ref}:{})},outputs:{track:id+'.track'},range:element.range}],exports:[id+'.track']};
  }});
 });
 const companion=createStudioTrackCompanionHostFacet(variants.map(v=>({id:definition.packageName.slice(1).replace('/','-')+'-'+v.name,role:'track',output:{type:compositionTypes.visualTrack,surface:v.name,modules:[module]},family:'frame-motion',label:definition.name,tone:'orange',icon:'component',lane:{heightPx:48},bindings:definition.parameters.map(p=>({name:p.key,writable:true,fallback:p.default})),inspector:definition.parameters.map(p=>({binding:p.key,label:p.label,domain:['x','y','scale','z'].includes(p.key)?'where':'how',section:{id:'motion',label:definition.name},control:p.type==='number'?'number':'text',...(p.type==='number'?{number:{step:p.step??0.1,...(p.min!==undefined?{min:p.min}:{}),...(p.max!==undefined?{max:p.max}:{})}}:{})})),project(context){return context.generic().map(item=>({...item,temporal:temporalLineageFor(context,context.placement.id,'window'),display:{title:definition.name,layers:[textLayer(definition.category+' · '+definition.name)]}}));}})));
 return {format:'hypit.node-package@1',modules:[{manifest}],components:[{producers:variants.map(v=>({producer:{module,name:v.name},handler:({inputs:i})=>({needs:{},outputs:{track:value(render(unwrap(i.timeline),unwrap(i.canvas),unwrap(i.window),unwrap(i.font),unwrap(i.options),v.image?i.image.value:null,Object.fromEntries(nativeIds.map(id=>[id,unwrap(i[id])]))))}})}))}],hostFacets:[...surfaces,companion]};
}
